/// 动画/过渡计时器（仅在 tick 和 interaction 中使用）
#[derive(Default)]
pub struct AnimationTimers {
    /// 背景过渡内部计时器
    pub bg_transition_elapsed: f32,
    /// 场景过渡内部计时器
    pub scene_transition_elapsed: f32,
    /// 活跃的 shake 动画状态
    pub active_shake: Option<ShakeAnimation>,
    /// 是否有活跃的场景效果（用于 signal 解析）
    pub scene_effect_active: bool,
}

/// Debug session 管理（完全隔离在 session.rs 中）
#[derive(Default)]
pub struct SessionAuthority {
    /// 当前持有 session authority 的客户端。
    pub client_owner: Option<SessionOwner>,
    /// client token 单调递增计数器。
    pub next_client_id: u64,
}

/// 应用状态内部结构（被 Mutex 保护）
pub struct AppStateInner {
    // ── 核心游戏状态 ──
    pub runtime: Option<vn_runtime::VNRuntime>,
    pub command_executor: CommandExecutor,
    pub render_state: RenderState,
    pub host_screen: HostScreen,
    pub waiting: WaitingFor,
    pub script_finished: bool,
    /// `setup()` 初始化的子系统集合
    pub services: Option<Services>,
    /// 对话历史（最新在前）
    pub history: Vec<HistoryEntry>,
    /// 用户设置
    pub user_settings: UserSettings,
    /// 持久化变量存储
    pub persistent_store: PersistentStore,
    /// 快照栈（Backspace 回退用）
    pub snapshot_stack: SnapshotStack,

    // ── 播放控制 ──
    /// 播放模式
    pub playback_mode: PlaybackMode,
    /// Auto 模式计时器
    pub auto_timer: f32,
    pub typewriter_timer: f32,
    /// 打字机基础速度（字符/秒）
    pub text_speed: f32,

    // ── 子结构 ──
    pub anim: AnimationTimers,
    pub session: SessionAuthority,
}

impl Default for AppStateInner {
    fn default() -> Self {
        Self::new()
    }
}

impl AppStateInner {
    pub fn new() -> Self {
        Self {
            runtime: None,
            command_executor: CommandExecutor::new(),
            render_state: RenderState::new(),
            host_screen: HostScreen::Title,
            waiting: WaitingFor::Nothing,
            script_finished: false,
            services: None,
            history: Vec::new(),
            user_settings: UserSettings::default(),
            persistent_store: PersistentStore::empty(),
            snapshot_stack: SnapshotStack::new(50),
            playback_mode: PlaybackMode::Normal,
            auto_timer: 0.0,
            typewriter_timer: 0.0,
            text_speed: 30.0,
            anim: AnimationTimers::default(),
            session: SessionAuthority::default(),
        }
    }

    /// 获取已初始化的子系统引用。
    /// `setup()` 完成后此断言不会失败。
    #[allow(
        clippy::expect_used,
        reason = "services absence after init is an engine invariant violation"
    )]
    pub fn services(&self) -> &Services {
        self.services
            .as_ref()
            .expect("invariant: services initialized in setup()")
    }

    /// 获取已初始化的子系统可变引用。
    #[allow(
        clippy::expect_used,
        reason = "services absence after init is an engine invariant violation"
    )]
    pub fn services_mut(&mut self) -> &mut Services {
        self.services
            .as_mut()
            .expect("invariant: services initialized in setup()")
    }

    pub(self) fn project_render_state(&mut self) {
        self.render_state.playback_mode = self.playback_mode.clone();
        self.render_state.host_screen = self.host_screen.clone();
    }
}

use dioxus::prelude::*;

/// Toast 消息类型（Warning/Info 暂无调用方，保留为完整 API）
#[derive(Debug, Clone, PartialEq)]
#[allow(
    dead_code,
    reason = "Warning/Info variants reserved for future callers"
)]
pub enum ToastType {
    Info,
    Success,
    Warning,
    Error,
}

/// 单条 Toast 消息
#[derive(Debug, Clone)]
pub struct ToastMessage {
    pub text: String,
    pub toast_type: ToastType,
    pub id: u64,
}

/// Toast 队列状态
#[derive(Debug, Clone, Default)]
pub struct ToastQueue {
    pub messages: Vec<ToastMessage>,
    next_id: u64,
}

// toast 各类型便捷方法：供未来 UI 屏幕调用，暂无调用方但保留为公开 API。
#[allow(
    dead_code,
    reason = "convenience methods reserved for future screen callers"
)]
impl ToastQueue {
    pub fn push(&mut self, text: impl Into<String>, toast_type: ToastType) {
        self.messages.push(ToastMessage {
            text: text.into(),
            toast_type,
            id: self.next_id,
        });
        self.next_id += 1;
    }

    pub fn success(&mut self, text: impl Into<String>) {
        self.push(text, ToastType::Success);
    }

    pub fn error(&mut self, text: impl Into<String>) {
        self.push(text, ToastType::Error);
    }

    pub fn info(&mut self, text: impl Into<String>) {
        self.push(text, ToastType::Info);
    }

    pub fn remove(&mut self, id: u64) {
        self.messages.retain(|m| m.id != id);
    }
}

/// Toast 渲染层（右上角固定）
#[component]
pub fn ToastLayer() -> Element {
    let mut toast_queue = use_context::<Signal<ToastQueue>>();
    let messages = toast_queue.read().messages.clone();

    if messages.is_empty() {
        return rsx! {};
    }

    rsx! {
        div { class: "toast-layer",
            for msg in &messages {
                {
                    let id = msg.id;
                    let text = msg.text.clone();
                    let modifier = match msg.toast_type {
                        ToastType::Info => "toast--info",
                        ToastType::Success => "toast--success",
                        ToastType::Warning => "toast--warning",
                        ToastType::Error => "toast--error",
                    };

                    rsx! {
                        div {
                            key: "{id}",
                            class: "toast {modifier}",
                            onanimationend: move |_| {
                                toast_queue.write().remove(id);
                            },
                            "{text}"
                        }
                    }
                }
            }
        }
    }
}

//! 资源清单（Manifest）
//!
//! 立绘元数据管理：角色组配置、锚点、预缩放、站位预设。

use crate::resources::normalize_logical_path;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;

/// 2D 点（归一化坐标）
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Point2D {
    pub x: f32,
    pub y: f32,
}

impl Default for Point2D {
    fn default() -> Self {
        Self { x: 0.5, y: 1.0 }
    }
}

/// 立绘组配置
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GroupConfig {
    pub anchor: Point2D,
    pub pre_scale: f32,
}

impl Default for GroupConfig {
    fn default() -> Self {
        Self {
            anchor: Point2D { x: 0.5, y: 1.0 },
            pre_scale: 1.0,
        }
    }
}

/// 站位预设
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PositionPreset {
    pub x: f32,
    pub y: f32,
    pub scale: f32,
}

impl Default for PositionPreset {
    fn default() -> Self {
        Self {
            x: 0.5,
            y: 0.95,
            scale: 1.0,
        }
    }
}

/// 角色配置
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CharactersConfig {
    #[serde(default)]
    pub groups: HashMap<String, GroupConfig>,
    #[serde(default)]
    pub sprites: HashMap<String, String>,
}

/// 默认配置
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DefaultsConfig {
    pub anchor: Point2D,
    pub pre_scale: f32,
}

impl Default for DefaultsConfig {
    fn default() -> Self {
        Self {
            anchor: Point2D { x: 0.5, y: 1.0 },
            pre_scale: 1.0,
        }
    }
}

/// manifest 启动期告警。
#[derive(Debug, Clone, Serialize)]
pub enum ManifestWarning {
    InvalidAnchor {
        name: String,
        x: f32,
        y: f32,
    },
    InvalidPreScale {
        name: String,
        value: f32,
    },
    InvalidPreset {
        name: String,
        x: f32,
        y: f32,
        scale: f32,
    },
    UnknownGroup {
        sprite_path: String,
        group: String,
    },
}

/// 资源清单
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Manifest {
    #[serde(default, rename = "$comment")]
    pub comment: Option<String>,
    #[serde(default)]
    pub characters: CharactersConfig,
    #[serde(default)]
    pub presets: HashMap<String, PositionPreset>,
    #[serde(default)]
    pub defaults: DefaultsConfig,
}

impl Manifest {
    pub fn parse_and_validate(
        content: &str,
    ) -> Result<(Self, Vec<ManifestWarning>), crate::error::HostError> {
        let manifest: Self = serde_json::from_str(content).map_err(|e| {
            crate::error::HostError::Internal(format!("无法解析 manifest JSON: {e}"))
        })?;
        let warnings = manifest.validate();
        Ok((manifest, warnings))
    }

    /// 创建带默认预设的空 Manifest（测试用）
    #[cfg(test)]
    pub fn with_defaults() -> Self {
        let mut presets = HashMap::new();
        for (name, x, y, scale) in [
            ("left", 0.15, 0.95, 1.0),
            ("nearleft", 0.25, 0.95, 1.0),
            ("farleft", 0.08, 0.90, 0.85),
            ("center", 0.50, 0.95, 1.0),
            ("nearmiddle", 0.40, 0.95, 1.0),
            ("farmiddle", 0.50, 0.90, 0.85),
            ("right", 0.85, 0.95, 1.0),
            ("nearright", 0.75, 0.95, 1.0),
            ("farright", 0.92, 0.90, 0.85),
        ] {
            presets.insert(name.to_string(), PositionPreset { x, y, scale });
        }
        Self {
            comment: None,
            characters: CharactersConfig::default(),
            presets,
            defaults: DefaultsConfig::default(),
        }
    }

    pub fn validate(&self) -> Vec<ManifestWarning> {
        let mut warnings = Vec::new();

        for (name, group) in &self.characters.groups {
            if !group.anchor.x.is_finite()
                || !group.anchor.y.is_finite()
                || !(0.0..=1.0).contains(&group.anchor.x)
                || !(0.0..=1.5).contains(&group.anchor.y)
            {
                warnings.push(ManifestWarning::InvalidAnchor {
                    name: name.clone(),
                    x: group.anchor.x,
                    y: group.anchor.y,
                });
            }
            if !group.pre_scale.is_finite() || group.pre_scale <= 0.0 {
                warnings.push(ManifestWarning::InvalidPreScale {
                    name: name.clone(),
                    value: group.pre_scale,
                });
            }
        }

        for (name, preset) in &self.presets {
            if !preset.x.is_finite()
                || !preset.y.is_finite()
                || !preset.scale.is_finite()
                || preset.scale <= 0.0
            {
                warnings.push(ManifestWarning::InvalidPreset {
                    name: name.clone(),
                    x: preset.x,
                    y: preset.y,
                    scale: preset.scale,
                });
            }
        }

        for (sprite_path, group) in &self.characters.sprites {
            if !self.characters.groups.contains_key(group) {
                warnings.push(ManifestWarning::UnknownGroup {
                    sprite_path: sprite_path.clone(),
                    group: group.clone(),
                });
            }
        }

        warnings
    }

    /// 获取立绘的组配置
    pub fn get_group_config(&self, sprite_path: &str) -> GroupConfig {
        let normalized_path = normalize_logical_path(sprite_path);

        if let Some(group_id) = self
            .characters
            .sprites
            .get(sprite_path)
            .or_else(|| self.characters.sprites.get(&normalized_path))
            && let Some(config) = self.characters.groups.get(group_id)
        {
            return config.clone();
        }

        let group_id = self.infer_group_id(&normalized_path);
        if let Some(config) = self.characters.groups.get(&group_id) {
            return config.clone();
        }

        GroupConfig {
            anchor: self.defaults.anchor,
            pre_scale: self.defaults.pre_scale,
        }
    }

    #[allow(
        clippy::string_slice,
        reason = "slicing at position from str::find, always a char boundary"
    )]
    fn infer_group_id(&self, sprite_path: &str) -> String {
        let path = Path::new(sprite_path);

        if let Some(parent) = path.parent()
            && let Some(parent_name) = parent.file_name()
        {
            let parent_str = parent_name.to_string_lossy();
            if !matches!(
                parent_str.as_ref(),
                "characters" | "sprites" | "images" | "assets"
            ) {
                return parent_str.to_string();
            }
        }

        if let Some(stem) = path.file_stem() {
            let stem_str = stem.to_string_lossy();
            for sep in ['-', '_', ' '] {
                if let Some(pos) = stem_str.find(sep) {
                    return stem_str[..pos].to_string();
                }
            }
            return stem_str.to_string();
        }

        "default".to_string()
    }

    /// 获取站位预设
    pub fn get_preset(&self, position_name: &str) -> PositionPreset {
        self.presets.get(position_name).cloned().unwrap_or_default()
    }
}

