105	impl Executor {
106	    /// 创建新的执行器
107	    pub fn new() -> Self {
108	        Self {}
109	    }
110	
111	    /// 执行单个脚本节点
112	    ///
113	    /// # 返回
114	    ///
115	    /// `ExecuteResult` 包含：
116	    /// - `commands`: 产生的指令
117	    /// - `waiting`: 如果需要等待，返回等待原因
118	    /// - `jump_to`: 如果需要跳转，返回目标位置
119	    pub fn execute(
120	        &mut self,
121	        node: &ScriptNode,
122	        state: &mut RuntimeState,
123	        script: &Script,
124	    ) -> Result<ExecuteResult, RuntimeError> {
125	        match node {
126	            ScriptNode::Chapter { title, level } => {
127	                Ok(ExecuteResult::with_commands(vec![Command::ChapterMark {
128	                    title: title.clone(),
129	                    level: *level,
130	                }]))
131	            }
132	
133	            ScriptNode::Label { .. } => {
134	                // 标签节点不产生 Command，只是跳转目标
135	                Ok(ExecuteResult::empty())
136	            }
137	
138	            ScriptNode::Dialogue {
139	                speaker,
140	                content,
141	                inline_effects,
142	                no_wait,
143	            } => Ok(ExecuteResult::with_wait(
144	                vec![Command::ShowText {
145	                    speaker: speaker.clone(),
146	                    content: content.clone(),
147	                    inline_effects: inline_effects.clone(),
148	                    no_wait: *no_wait,
149	                }],
150	                WaitingReason::WaitForClick,
151	            )),
152	
153	            ScriptNode::Extend {
154	                content,
155	                inline_effects,
156	                no_wait,
157	            } => Ok(ExecuteResult::with_wait(
158	                vec![Command::ExtendText {
159	                    content: content.clone(),
160	                    inline_effects: inline_effects.clone(),
161	                    no_wait: *no_wait,
162	                }],
163	                WaitingReason::WaitForClick,
164	            )),
165	
166	            ScriptNode::ChangeBG { path, transition } => {
167	                // 解析路径（相对于脚本目录）
168	                let resolved_path = script.resolve_path(path);
169	                // 更新状态
170	                state.current_background = Some(resolved_path.clone());
171	
172	                Ok(ExecuteResult::with_commands(vec![
173	                    Command::ShowBackground {
174	                        path: resolved_path,
175	                        transition: transition.clone(),
176	                    },
177	                ]))
178	            }
179	
180	            ScriptNode::ChangeScene { path, transition } => {
181	                // 解析路径（相对于脚本目录）
182	                let resolved_path = script.resolve_path(path);
183	                // 更新状态
184	                state.current_background = Some(resolved_path.clone());
185	
186	                // 解析 transition 中的路径参数（如 rule 效果的 mask 路径）
187	                let resolved_transition = transition.as_ref().map(|t| {
188	                    let mut new_transition = t.clone();
189	                    // 遍历参数，解析路径类型的字符串
190	                    new_transition.args = t
191	                        .args
192	                        .iter()
193	                        .map(|(key, arg)| {
194	                            if let Some(k) = key {
195	                                // 命名参数：mask 参数需要解析路径
196	                                if k == "mask"
197	                                    && let crate::command::TransitionArg::String(s) = arg
198	                                {
199	                                    return (
200	                                        Some(k.clone()),
201	                                        crate::command::TransitionArg::String(
202	                                            script.resolve_path(s),
203	                                        ),
204	                                    );
205	                                }
206	                            }
207	                            (key.clone(), arg.clone())
208	                        })
209	                        .collect();
210	                    new_transition
211	                });
212	
213	                let commands = vec![Command::ChangeScene {
214	                    path: resolved_path,
215	                    transition: resolved_transition.clone(),
216	                }];
217	
218	                if resolved_transition.is_some() {
219	                    Ok(ExecuteResult::with_wait(
220	                        commands,
221	                        WaitingReason::WaitForSignal(SignalId::new(
222	                            crate::command::SIGNAL_SCENE_TRANSITION,
223	                        )),
224	                    ))
225	                } else {
226	                    Ok(ExecuteResult::with_commands(commands))
227	                }
228	            }
229	
230	            ScriptNode::ShowCharacter {
231	                path,
232	                alias,
233	                position,
234	                transition,
235	            } => {
236	                // 如果 path 为 None，尝试从已绑定的别名中查找
237	                let resolved_path = if let Some(p) = path {
238	                    // 有路径：解析路径（相对于脚本目录）并绑定别名
239	                    let resolved = script.resolve_path(p);
240	                    // 更新状态
