//! - [`parser`]：两阶段解析器实现

pub mod ast;
pub mod expr;
pub mod parser;

pub use ast::*;
pub use expr::{EvalContext, EvalError, Expr, evaluate, evaluate_to_bool};
pub use parser::Parser;

//! # State 模块
//!
//! 定义 Runtime 的运行时状态和等待模型。
//!
//! ## 设计原则
//!
//! - 所有状态必须**显式建模**
//! - 所有状态必须**可序列化**（支持存档/读档）
//! - 不允许隐式全局状态

use std::{collections::HashMap, time::Duration};

use serde::{Deserialize, Serialize};

use crate::input::SignalId;

/// 等待原因
///
/// Runtime 在执行过程中可能进入等待状态，需要特定输入才能继续。
/// Host 根据此状态决定如何采集输入。
///
/// # 状态转换
///
/// ```text
/// None          -> 继续执行，不等待
/// WaitForClick  -> 等待用户点击，收到 Click 输入后继续
/// WaitForChoice -> 等待用户选择，收到 ChoiceSelected 输入后继续
/// WaitForTime   -> Host 等待指定时长后调用 tick，Runtime 自动继续
/// WaitForSignal -> 等待外部信号，收到匹配的 Signal 输入后继续
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum WaitingReason {
    /// 不等待，继续执行
    None,

    /// 等待用户点击
    WaitForClick,

    /// 等待用户选择
    ///
    /// `choice_count` 记录选项数量，用于验证输入合法性
    WaitForChoice { choice_count: usize },

    /// 等待指定时长
    ///
    /// Host 获取此状态后，等待指定时长再调用 tick。
    /// Runtime 不需要知道真实时间流逝。
    WaitForTime(Duration),

    /// 等待外部信号
    WaitForSignal(SignalId),

    /// 等待 UI 交互结果
    ///
    /// Runtime 发出 `Command::RequestUI` 后进入此状态。
    /// 收到匹配的 `RuntimeInput::UIResult` 后，将 `value` 存入
    /// `result_var` 指定的脚本变量，然后清除等待。
    WaitForUIResult {
        /// 请求标识符（与 UIResult.key 配对）
        key: String,

